{
  "passageId": "corporate-law",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법인이 독립된 권리·의무의 주체라는 법적 지위에서 자산 소유권의 귀속에 관한 판단을 도출하므로 근거·도출이다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인에게 행위 능력이 없다는 한계를 권한을 부여받은 사람의 자산 운용으로 보완하므로 문제·대응이다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "자산 운용 권한을 부여받았더라도 절차와 목적을 위반하면 처벌받는다는 권한의 한계를 제시하므로 양보·한계이다."
    },
    {
      "id": "R4",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "자산 운용에 대한 법적 통제를 통해 공동체의 질서를 유지하려 하므로 수단·목적이다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "재단 법인과 사단 법인의 일반적 구분을 장학 재단이라는 구체적 사례로 보여 주므로 구체화·예시이다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "영리성에 따른 법인 구분에서 비영리 법인의 사례로 장학 재단을 제시하므로 구체화·예시이다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장학 재단이 비영리 법인이라는 사실과 그 범주의 뜻으로부터 경제적 이익을 추구하지 않는다는 판단을 도출하므로 근거·도출이다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장학 재단이 재단 법인이라는 사실로부터 법인격의 부여 대상이 자산 자체라는 판단이 따라 나오므로 근거·도출이다."
    },
    {
      "id": "R9",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인의 행위 능력 부재를 보완하기 위해 대신 행위할 이사회를 설치하므로 문제·대응이다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "이사회가 결정권자가 아니라는 설명을 주요 사항에 대한 관할 기관의 허가 요건으로 구체화하므로 구체화·예시이다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "허가가 필요한 주요 사항의 구체적인 사례로 기본 재산의 처분과 용도 변경에 따른 감액을 제시하므로 구체화·예시이다."
    },
    {
      "id": "R12",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익 추구가 가능하더라도 영리 목적까지 허용되는 것은 아니라는 한계를 제시하므로 양보·한계이다."
    },
    {
      "id": "R13",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "기본 재산과 그 밖의 자산을 운용 요건이라는 동일한 기준에서 비교하여 차이를 드러내므로 대조이다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법인 종류에 따라 통제 내용이 다르다는 일반적 설명을 주식회사의 법적 통제 방식으로 구체화하므로 구체화·예시이다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "구체적 요건과 절차를 정한 상법도 적용된다는 사실을 근거로 통제가 더 정교하다고 평가하므로 근거·도출이다."
    },
    {
      "id": "R16",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "장학 재단과 주식회사를 법인격의 부여 대상이라는 같은 기준에서 비교하므로 대조이다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "재단 법인과 주식회사의 자산 운용 주체가 갖는 결정권의 차이를 비교하므로 대조이다."
    },
    {
      "id": "R18",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "개인의 출자로 형성된 자산도 법인에 귀속된다는 일반 원칙을 주주의 출자로 자산이 형성되는 주식회사 사례에 연결하므로 원리 적용이다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자본금이 지급 능력과 재무 안정성을 보장한다는 기능을 감액 금지 원칙의 근거로 제시하므로 근거·도출이다."
    },
    {
      "id": "R20",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "이익 잉여금과 자본 잉여금을 사용 목적과 배당 가능 여부라는 같은 기준에서 비교하므로 대조이다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "자본금 감액 금지라는 원칙에 대해 잉여금으로 손실을 보전할 수 없는 경우의 예외를 제시하므로 양보·한계이다."
    },
    {
      "id": "R22",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "자본금 감소가 회사의 존립을 위협한다는 위험에 대한 대응으로 신중한 자산 운용을 요구하므로 문제·대응이다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주식회사의 자산 운용 통제가 정교하다는 설명을 무상 증자와 배당의 상이한 실행 요건으로 구체화하므로 구체화·예시이다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "재무 구조가 안정적이라는 인상이 실제 시장에서 주가 상승을 유발할 수 있다는 작용을 설명하므로 인과·작용이다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자산 총규모가 변하지 않는다는 특성을 이사회 결정만으로 실행할 수 있는 이유로 제시하므로 근거·도출이다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "배당이 자산의 외부 유출이라는 사실을 더 까다로운 실행 요건이 필요한 근거로 제시하므로 근거·도출이다."
    },
    {
      "id": "R27",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "까다로운 의결 요건을 통해 잘못된 판단에 따른 회사와 주주의 손해를 막으려 하므로 수단·목적이다."
    },
    {
      "id": "R28",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "무상 증자와 배당을 자산의 외부 유출 여부 및 실행 요건이라는 같은 기준에서 비교하므로 대조이다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "배당이 무엇인지 제시한 뒤 동일한 대상의 기대 효과와 실행 요건을 자세히 설명하므로 구체화·예시이다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법적 통제의 일반적인 목적을 배당 통제에서의 회사와 주주 손해 방지라는 구체적인 목적으로 풀어 제시하므로 구체화·예시이다."
    }
  ]
}

